(()=>{"use strict";const e=document.querySelector(".card"),s=document.querySelector(".feed"),n=document.querySelector(".error"),i=document.querySelector(".card__refresh");function t(e){const s=new AbortController;return setTimeout(()=>s.abort(),e),s.signal}async function r(){e.classList.remove("is-error"),n.classList.add("hidden"),s.innerHTML='\n  <li class="news">\n    <div class="news__category skeleton"></div>\n    <div class="news__row">\n      <div class="news__image skeleton"></div>\n      <div class="news__text">\n        <div class="news__line skeleton"></div>\n        <div class="news__line skeleton"></div>\n      </div>\n    </div>\n  </li>'.repeat(3);try{const r=await fetch("https://remarkable-cassata-5e99fd.netlify.app/.netlify/functions/news",{signal:t(1e4)});if(!r.ok)throw new Error(`HTTP ${r.status}`);i=await r.json(),e.classList.remove("is-error"),n.classList.add("hidden"),s.innerHTML=i.map(e=>`\n    <li class="news">\n      <div class="news__title">${e.category}</div>\n      <div class="news__row">\n        <img class="news__img" src="${e.image}" alt="" />\n        <div class="news__text">\n          <p class="news__title">${e.title}</p>\n          <p class="news__desc">${e.description}</p>\n        </div>\n      </div>\n    </li>`).join("")}catch(s){e.classList.add("is-error"),n.classList.remove("hidden")}var i}i.addEventListener("click",e=>{e.preventDefault(),r()}),r(),"serviceWorker"in navigator&&window.addEventListener("load",()=>{navigator.serviceWorker.register("sw.js")})})();